import test from 'node:test';
import assert from 'node:assert/strict';
import { normalizeId, getCustomer, listCustomers, mergeCustomers } from '../src/customers.js';

test('normalizeId trims whitespace', () => {
  assert.equal(normalizeId('  c-001  '), 'C-001');
});

test('normalizeId converts to uppercase', () => {
  assert.equal(normalizeId('c-001'), 'C-001');
});

test('getCustomer returns customer for valid id', () => {
  const result = getCustomer('C-001');
  assert.equal(result.ok, true);
  assert.equal(result.value.id, 'C-001');
});

test('getCustomer normalizes id', () => {
  const result = getCustomer('  c-001  ');
  assert.equal(result.ok, true);
  assert.equal(result.value.id, 'C-001');
});

test('getCustomer returns error for unknown id', () => {
  const result = getCustomer('C-999');
  assert.deepEqual(result, { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('listCustomers returns all customers', () => {
  const customers = listCustomers();
  assert.ok(Array.isArray(customers));
  assert.ok(customers.length > 0);
});

test('listCustomers does not mutate', () => {
  const customers1 = listCustomers();
  const customers2 = listCustomers();
  customers1[0].name = 'Modified';
  assert.notEqual(customers2[0].name, 'Modified');
});

test('mergeCustomers moves invoices from one customer to another', () => {
  const customers = [
    { id: 'C-001', name: 'Customer 1', email: 'c1@example.com', country: 'NL', tier: 'gold' },
    { id: 'C-002', name: 'Customer 2', email: 'c2@example.com', country: 'NL', tier: 'silver' },
  ];
  const invoices = [
    { customerId: 'C-001', issueDate: '2024-01-15', lines: [] },
    { customerId: 'C-001', issueDate: '2024-02-15', lines: [] },
    { customerId: 'C-002', issueDate: '2024-03-15', lines: [] },
  ];

  const result = mergeCustomers(customers, invoices, 'C-001', 'C-002');
  assert.equal(result.ok, true);
  assert.equal(result.value.customers.length, 1);
  assert.equal(result.value.invoices.length, 3);
  assert.equal(result.value.invoices[0].customerId, 'C-002');
  assert.equal(result.value.invoices[1].customerId, 'C-002');
  assert.equal(result.value.invoices[2].customerId, 'C-002');
});

test('mergeCustomers removes fromId customer', () => {
  const customers = [
    { id: 'C-001', name: 'Customer 1', email: 'c1@example.com', country: 'NL', tier: 'gold' },
    { id: 'C-002', name: 'Customer 2', email: 'c2@example.com', country: 'NL', tier: 'silver' },
  ];
  const invoices = [];

  const result = mergeCustomers(customers, invoices, 'C-001', 'C-002');
  assert.equal(result.ok, true);
  const ids = result.value.customers.map((c) => c.id);
  assert.ok(!ids.includes('C-001'));
  assert.ok(ids.includes('C-002'));
});

test('mergeCustomers keeps intoId customer', () => {
  const customers = [
    { id: 'C-001', name: 'Customer 1', email: 'c1@example.com', country: 'NL', tier: 'gold' },
    { id: 'C-002', name: 'Customer 2', email: 'c2@example.com', country: 'NL', tier: 'silver' },
  ];
  const invoices = [];

  const result = mergeCustomers(customers, invoices, 'C-001', 'C-002');
  assert.equal(result.ok, true);
  const intoCustomer = result.value.customers.find((c) => c.id === 'C-002');
  assert.ok(intoCustomer);
});

test('mergeCustomers normalizes customer ids', () => {
  const customers = [
    { id: 'C-001', name: 'Customer 1', email: 'c1@example.com', country: 'NL', tier: 'gold' },
    { id: 'C-002', name: 'Customer 2', email: 'c2@example.com', country: 'NL', tier: 'silver' },
  ];
  const invoices = [{ customerId: 'C-001', issueDate: '2024-01-15', lines: [] }];

  const result = mergeCustomers(customers, invoices, '  c-001  ', 'C-002');
  assert.equal(result.ok, true);
  assert.equal(result.value.invoices[0].customerId, 'C-002');
});

test('mergeCustomers returns error for unknown fromId', () => {
  const customers = [
    { id: 'C-001', name: 'Customer 1', email: 'c1@example.com', country: 'NL', tier: 'gold' },
  ];
  const invoices = [];

  const result = mergeCustomers(customers, invoices, 'C-999', 'C-001');
  assert.deepEqual(result, { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('mergeCustomers returns error for unknown intoId', () => {
  const customers = [
    { id: 'C-001', name: 'Customer 1', email: 'c1@example.com', country: 'NL', tier: 'gold' },
  ];
  const invoices = [];

  const result = mergeCustomers(customers, invoices, 'C-001', 'C-999');
  assert.deepEqual(result, { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('mergeCustomers returns error for same customer', () => {
  const customers = [
    { id: 'C-001', name: 'Customer 1', email: 'c1@example.com', country: 'NL', tier: 'gold' },
  ];
  const invoices = [];

  const result = mergeCustomers(customers, invoices, 'C-001', 'C-001');
  assert.deepEqual(result, { ok: false, error: 'SAME_CUSTOMER' });
});

test('mergeCustomers returns error for same customer with different case', () => {
  const customers = [
    { id: 'C-001', name: 'Customer 1', email: 'c1@example.com', country: 'NL', tier: 'gold' },
  ];
  const invoices = [];

  const result = mergeCustomers(customers, invoices, 'c-001', 'C-001');
  assert.deepEqual(result, { ok: false, error: 'SAME_CUSTOMER' });
});

test('mergeCustomers does not mutate input arrays', () => {
  const customers = [
    { id: 'C-001', name: 'Customer 1', email: 'c1@example.com', country: 'NL', tier: 'gold' },
    { id: 'C-002', name: 'Customer 2', email: 'c2@example.com', country: 'NL', tier: 'silver' },
  ];
  const invoices = [
    { customerId: 'C-001', issueDate: '2024-01-15', lines: [] },
  ];

  const customersLen = customers.length;
  const invoicesLen = invoices.length;

  mergeCustomers(customers, invoices, 'C-001', 'C-002');

  assert.equal(customers.length, customersLen);
  assert.equal(invoices.length, invoicesLen);
  assert.equal(invoices[0].customerId, 'C-001');
});

test('mergeCustomers with no invoices', () => {
  const customers = [
    { id: 'C-001', name: 'Customer 1', email: 'c1@example.com', country: 'NL', tier: 'gold' },
    { id: 'C-002', name: 'Customer 2', email: 'c2@example.com', country: 'NL', tier: 'silver' },
  ];
  const invoices = [];

  const result = mergeCustomers(customers, invoices, 'C-001', 'C-002');
  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 0);
  assert.equal(result.value.customers.length, 1);
});

test('mergeCustomers with multiple customers and invoices', () => {
  const customers = [
    { id: 'C-001', name: 'Customer 1', email: 'c1@example.com', country: 'NL', tier: 'gold' },
    { id: 'C-002', name: 'Customer 2', email: 'c2@example.com', country: 'NL', tier: 'silver' },
    { id: 'C-003', name: 'Customer 3', email: 'c3@example.com', country: 'NL', tier: 'standard' },
  ];
  const invoices = [
    { customerId: 'C-001', issueDate: '2024-01-15', lines: [] },
    { customerId: 'C-002', issueDate: '2024-02-15', lines: [] },
    { customerId: 'C-001', issueDate: '2024-03-15', lines: [] },
    { customerId: 'C-003', issueDate: '2024-04-15', lines: [] },
  ];

  const result = mergeCustomers(customers, invoices, 'C-001', 'C-002');
  assert.equal(result.ok, true);
  assert.equal(result.value.customers.length, 2);
  assert.equal(result.value.invoices.length, 4);

  const c001Invoices = result.value.invoices.filter((inv) => inv.customerId === 'C-001');
  assert.equal(c001Invoices.length, 0);

  const c002Invoices = result.value.invoices.filter((inv) => inv.customerId === 'C-002');
  assert.equal(c002Invoices.length, 3);

  const c003Invoices = result.value.invoices.filter((inv) => inv.customerId === 'C-003');
  assert.equal(c003Invoices.length, 1);
});

test('mergeCustomers preserves invoice properties', () => {
  const customers = [
    { id: 'C-001', name: 'Customer 1', email: 'c1@example.com', country: 'NL', tier: 'gold' },
    { id: 'C-002', name: 'Customer 2', email: 'c2@example.com', country: 'NL', tier: 'silver' },
  ];
  const invoices = [
    {
      customerId: 'C-001',
      issueDate: '2024-01-15',
      dueDate: '2024-02-14',
      status: 'issued',
      lines: [{ sku: 'DES-HOUR', qty: 10 }],
    },
  ];

  const result = mergeCustomers(customers, invoices, 'C-001', 'C-002');
  assert.equal(result.ok, true);
  const mergedInvoice = result.value.invoices[0];
  assert.equal(mergedInvoice.customerId, 'C-002');
  assert.equal(mergedInvoice.issueDate, '2024-01-15');
  assert.equal(mergedInvoice.dueDate, '2024-02-14');
  assert.equal(mergedInvoice.status, 'issued');
  assert.deepEqual(mergedInvoice.lines, [{ sku: 'DES-HOUR', qty: 10 }]);
});

test('mergeCustomers preserves customer properties', () => {
  const customers = [
    { id: 'C-001', name: 'Customer 1', email: 'c1@example.com', country: 'NL', tier: 'gold' },
    { id: 'C-002', name: 'Customer 2', email: 'c2@example.com', country: 'NL', tier: 'silver' },
  ];
  const invoices = [];

  const result = mergeCustomers(customers, invoices, 'C-001', 'C-002');
  assert.equal(result.ok, true);
  const c002 = result.value.customers.find((c) => c.id === 'C-002');
  assert.equal(c002.name, 'Customer 2');
  assert.equal(c002.email, 'c2@example.com');
  assert.equal(c002.country, 'NL');
  assert.equal(c002.tier, 'silver');
});

test('mergeCustomers with whitespace in ids', () => {
  const customers = [
    { id: 'C-001', name: 'Customer 1', email: 'c1@example.com', country: 'NL', tier: 'gold' },
    { id: 'C-002', name: 'Customer 2', email: 'c2@example.com', country: 'NL', tier: 'silver' },
  ];
  const invoices = [{ customerId: 'C-001', issueDate: '2024-01-15', lines: [] }];

  const result = mergeCustomers(customers, invoices, '  c-001  ', '  C-002  ');
  assert.equal(result.ok, true);
  assert.equal(result.value.invoices[0].customerId, 'C-002');
});
